contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call buyCreditMarket as msg.sender = this contract. To provide tokens balance checks
    // we only can observe via public functions on c: specifically data().borrowAToken.balanceOf(account)
    // However borrowAToken is NonTransferrableScaledToken which exposes balanceOf public. We cannot mint tokens here,
    // but the checker will deploy a fresh C and may initialize state so we must avoid assumptions. The property we assert
    // is: when we call buyCreditMarket with exactAmountIn==true, then either the call reverts, or
    // the sum of decreases in caller borrowAToken balance equals the cashAmountIn transferred out (i.e., the amount taken from caller equals sum to borrower + feeRecipient). We observe balances before/after for caller and feeRecipient and assert non-negativity and conservation.

    // Note: We cannot read internals like cashAmountIn returned by executeBuyCreditMarket; but after the external call, the protocol should have transferred tokens using transferFrom: balances of caller should have decreased and recipients increased. We assert that caller decrease equals sum of recipient increases. If call reverts, that's allowed.

    function run(address borrower, uint256 creditPositionId, uint256 amount, uint256 tenor, uint256 deadline, uint256 minAPR) public payable {
        require(true);

        // Prepare params struct encoding for BuyCreditMarketParams
        bytes memory data = abi.encodeWithSelector(
            c.buyCreditMarket.selector,
            BuyCreditMarketParams({
                borrower: borrower,
                creditPositionId: creditPositionId,
                amount: amount,
                tenor: tenor,
                deadline: deadline,
                minAPR: minAPR,
                exactAmountIn: true
            })
        );

        // Read borrowAToken address and feeRecipient via public views
        ISizeView.DataView memory dv = c.data();
        address borrowAToken = address(dv.borrowAToken);
        address feeRecipient = c.feeConfig().feeRecipient;

        // Observe balances before
        uint256 balCallerBefore = NonTransferrableScaledToken(borrowAToken).balanceOf(address(this));
        uint256 balBorrowerBefore = NonTransferrableScaledToken(borrowAToken).balanceOf(borrower);
        uint256 balFeeBefore = NonTransferrableScaledToken(borrowAToken).balanceOf(feeRecipient);

        bool reverted = false;
        // Call buyCreditMarket forwarding no ETH (we don't rely on msg.value)
        try c.buyCreditMarket{value: 0}(BuyCreditMarketParams({
            borrower: borrower,
            creditPositionId: creditPositionId,
            amount: amount,
            tenor: tenor,
            deadline: deadline,
            minAPR: minAPR,
            exactAmountIn: true
        })) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balances after
        uint256 balCallerAfter = NonTransferrableScaledToken(borrowAToken).balanceOf(address(this));
        uint256 balBorrowerAfter = NonTransferrableScaledToken(borrowAToken).balanceOf(borrower);
        uint256 balFeeAfter = NonTransferrableScaledToken(borrowAToken).balanceOf(feeRecipient);

        // Compute deltas (in unsigned safe manner)
        uint256 callerDecrease = balCallerBefore >= balCallerAfter ? balCallerBefore - balCallerAfter : 0;
        uint256 borrowerIncrease = balBorrowerAfter >= balBorrowerBefore ? balBorrowerAfter - balBorrowerBefore : 0;
        uint256 feeIncrease = balFeeAfter >= balFeeBefore ? balFeeAfter - balFeeBefore : 0;

        // General rule: either the call reverted, or the decrease in caller balance equals sum of increases of borrower and feeRecipient
        assert(reverted || callerDecrease == borrowerIncrease + feeIncrease);
    }

    // Minimal interfaces mirroring types used from the existing compilation unit
    struct BuyCreditMarketParams { address borrower; uint256 creditPositionId; uint256 amount; uint256 tenor; uint256 deadline; uint256 minAPR; bool exactAmountIn; }

    // We declare small interfaces to call public view methods on external contracts
    interface ISizeView { function data() external view returns (ISizeView.DataView memory); function feeConfig() external view returns (InitializeFeeConfigParams memory); struct DataView { uint256 nextDebtPositionId; uint256 nextCreditPositionId; IERC20Metadata underlyingCollateralToken; IERC20Metadata underlyingBorrowToken; IPool variablePool; NonTransferrableToken collateralToken; NonTransferrableScaledToken borrowAToken; NonTransferrableToken debtToken; } }

    // Re-declare small structs used in view returns
    struct InitializeFeeConfigParams { uint256 swapFeeAPR; uint256 fragmentationFee; uint256 liquidationRewardPercent; uint256 overdueCollateralProtocolPercent; uint256 collateralProtocolPercent; address feeRecipient; }

    // Minimal interfaces for tokens used only to call balanceOf
    interface IERC20Metadata { function decimals() external view returns (uint8); }
    abstract contract NonTransferrableScaledToken {
        function balanceOf(address account) public view virtual returns (uint256) {}
    }
    abstract contract NonTransferrableToken {
        function balanceOf(address account) public view virtual returns (uint256) {}
    }
    // Minimal IPool to satisfy compilation in struct types
    interface IPool { }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We assert a conservation property for buyCreditMarket exactAmountIn=true: if it doesn't revert,
    // the caller's borrowAToken balance decrease equals borrower increase + feeRecipient increase.
    // All observations are via public view functions.
    function run(address borrower, uint256 creditPositionId, uint256 amount, uint256 tenor, uint256 deadline, uint256 minAPR) public payable {
        require(true);

        // Read data view to get borrowAToken address
        ISizeView.DataView memory dv = c.data();
        address borrowATokenAddr = address(dv.borrowAToken);

        // Read feeRecipient from feeConfig
        InitializeFeeConfigParams memory fcfg = c.feeConfig();
        address feeRecipient = fcfg.feeRecipient;

        // Observe balances before (scaled borrowAToken balances are exposed via borrowAToken.balanceOf)
        uint256 balCallerBefore = NonTransferrableScaledToken(borrowATokenAddr).balanceOf(address(this));
        uint256 balBorrowerBefore = NonTransferrableScaledToken(borrowATokenAddr).balanceOf(borrower);
        uint256 balFeeBefore = NonTransferrableScaledToken(borrowATokenAddr).balanceOf(feeRecipient);

        bool reverted;
        // Call buyCreditMarket with exactAmountIn = true. We do not forward ETH.
        try c.buyCreditMarket{value: 0}(BuyCreditMarketParams({
            borrower: borrower,
            creditPositionId: creditPositionId,
            amount: amount,
            tenor: tenor,
            deadline: deadline,
            minAPR: minAPR,
            exactAmountIn: true
        })) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balances after
        uint256 balCallerAfter = NonTransferrableScaledToken(borrowATokenAddr).balanceOf(address(this));
        uint256 balBorrowerAfter = NonTransferrableScaledToken(borrowATokenAddr).balanceOf(borrower);
        uint256 balFeeAfter = NonTransferrableScaledToken(borrowATokenAddr).balanceOf(feeRecipient);

        // Compute deltas safely (no underflow in assert by using comparisons)
        uint256 callerDecrease = balCallerBefore >= balCallerAfter ? balCallerBefore - balCallerAfter : 0;
        uint256 borrowerIncrease = balBorrowerAfter >= balBorrowerBefore ? balBorrowerAfter - balBorrowerBefore : 0;
        uint256 feeIncrease = balFeeAfter >= balFeeBefore ? balFeeAfter - balFeeBefore : 0;

        // General invariant: either call reverted, or callerDecrease == borrowerIncrease + feeIncrease
        assert(reverted || callerDecrease == borrowerIncrease + feeIncrease);
    }

    // Minimal external types to match C's public API return types used above.
    struct BuyCreditMarketParams { address borrower; uint256 creditPositionId; uint256 amount; uint256 tenor; uint256 deadline; uint256 minAPR; bool exactAmountIn; }

    // Mirror of InitializeFeeConfigParams used by c.feeConfig()
    struct InitializeFeeConfigParams { uint256 swapFeeAPR; uint256 fragmentationFee; uint256 liquidationRewardPercent; uint256 overdueCollateralProtocolPercent; uint256 collateralProtocolPercent; address feeRecipient; }

    // Minimal subset of ISizeView.DataView used
    interface ISizeView {
        struct DataView { uint256 nextDebtPositionId; uint256 nextCreditPositionId; address underlyingCollateralToken; address underlyingBorrowToken; IPool variablePool; NonTransferrableToken collateralToken; NonTransferrableScaledToken borrowAToken; NonTransferrableToken debtToken; }
        function data() external view returns (DataView memory);
    }

    // Minimal token interfaces to call balanceOf
    interface NonTransferrableScaledToken { function balanceOf(address account) external view returns (uint256); }
    interface NonTransferrableToken { function balanceOf(address account) external view returns (uint256); }
    interface IPool { }

    // Forward feeConfig and data() calls to c via these wrappers to satisfy the compiler types
    // Note: direct calls to c.feeConfig() and c.data() in run used the real contract; here we only needed the structs.

    receive() external payable {}
}

