        // Note: getUserView returns borrowATokenBalance and collateralTokenBalance for the given account
        // We query for address(this) since this contract will be the caller of c.withdraw
        ( , ) = c.data(); // allowed view to ensure readability; not used further
        uint256 beforeCollateral = c.getUserView(address(this)).collateralTokenBalance;
        uint256 beforeBorrowAToken = c.getUserView(address(this)).borrowATokenBalance;
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        try c.withdraw{value: 0}(WithdrawParams({ token: token, amount: amount, to: to })) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCollateral = c.getUserView(address(this)).collateralTokenBalance;
        uint256 afterBorrowAToken = c.getUserView(address(this)).borrowATokenBalance;
        uint256 cBalAfter = address(c).balance;

        // The rule: either the call reverted and both reported balances unchanged and contract ETH unchanged,
        // or it succeeded and exactly one of the Size token balances (the one corresponding to `token`) decreased by at most `amount` and none increased, and contract ETH balance did not increase.
        // We cannot inspect which token type `token` is other than comparing addresses to underlying tokens exposed in data(),
