        if (reverted) {
            ok = (afterCollateral == beforeCollateral) && (afterBorrowAToken == beforeBorrowAToken) && (cBalAfter == cBalBefore);
        } else {
            // success: c's ETH balance must not increase
            bool ethUnchangedOrDecreased = cBalAfter <= cBalBefore;
            // collateral case: collateral balance of caller may decrease by at most `amount`, borrow balance unchanged
            bool collateralCase = tokenIsCollateral
                && afterBorrowAToken == beforeBorrowAToken
                && afterCollateral <= beforeCollateral
                && beforeCollateral - afterCollateral <= amount;
            // borrow case: borrowAToken balance of caller may decrease by at most `amount`, collateral unchanged
            bool borrowCase = tokenIsBorrow
                && afterCollateral == beforeCollateral
                && afterBorrowAToken <= beforeBorrowAToken
                && beforeBorrowAToken - afterBorrowAToken <= amount;
            // if token is neither known underlying, disallow success (should revert)
            bool unknownTokenCase = (!tokenIsCollateral && !tokenIsBorrow) ? false : true;

            ok = ethUnchangedOrDecreased && unknownTokenCase && (collateralCase || borrowCase);
        }

        assert(ok);
    }

    receive() external payable {}
}

