        // We can call c.getUserView(to) to get borrowATokenBalance
        ISize.UserView memory beforeView = c.getUserView(to);
        uint256 beforeBorrowATokenBalance = beforeView.borrowATokenBalance;

        // Attempt deposit: prepare DepositParams struct encoding
        bytes memory depositCalldata = abi.encodeWithSelector(
            c.deposit.selector,
            // DepositParams { address token; uint256 amount; address to; }
            // as calldata tuple
            (underlyingBorrowToken),
