    function run(bytes[] calldata calls) public payable {
        // require a non-empty batch to exercise multicall behavior
        require(calls.length > 0);

        // observe borrowAToken total supply before
        ( , , , , , ) = c.getPositionsCount(); // harmless view to ensure visibility (not required)
        uint256 before = c.data().borrowAToken.totalSupply();

