        // If the multicall reverted, the state must be unchanged so after == before.
        // If it didn't revert, the protocol should not have allowed borrowAToken totalSupply to decrease.
        assert(reverted ? after == before : after >= before);
    }

    // allow receiving ETH if some calls send value back
    receive() external payable {}
}

