contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as inputs: token address, amount to deposit, recipient `to`.
    // The test will call deposit with token == underlyingBorrowToken and assert properties about borrowAToken supply/balances.
    function run(address token, uint256 amount, address to) public payable {
        require(amount != 0, "avoid zero amount");
        // read data view before
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount(); // just to exercise view
        // get DataView to observe borrowAToken and underlyingBorrowToken address
        ISizeView.DataView memory dv = c.data();

        // Precondition: token must equal the protocol's underlying borrow token to exercise depositUnderlyingBorrowToken path
        require(token == address(dv.underlyingBorrowToken), "token must be underlyingBorrowToken");
        // require this contract has enough balance to send `amount` of ERC20: since we cannot mint tokens here,
        // the checker will arrange balances or this call may revert; to avoid reading balances we simply proceed.

        // Observe borrowAToken total supply before (unscaled totalSupply exposed by NonTransferrableScaledToken.totalSupply())
        uint256 borrowATokenTotalBefore = dv.borrowAToken.totalSupply();
        // Observe this contract's borrowAToken balance before (unscaled view)
        uint256 balanceBefore = dv.borrowAToken.balanceOf(address(this));

        // Prepare calldata for deposit: DepositParams(token, amount, to)
        // Call deposit on C. It may revert; capture whether it reverted.
        bool reverted = false;
        try c.deposit{value: msg.value}(ISize.DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-states via public views regardless of revert (views may revert if state invalid, but okay)
        ISizeView.DataView memory dvAfter = c.data();
        uint256 borrowATokenTotalAfter = dvAfter.borrowAToken.totalSupply();
        uint256 balanceAfter = dvAfter.borrowAToken.balanceOf(address(this));

        // General rule: If deposit succeeded (not reverted) and token == underlyingBorrowToken,
        // then borrowAToken.totalSupply() must not decrease, and either the total supply increased or
        // the caller's borrowAToken balance did not decrease.
        // This captures monotonicity of supply on deposits and that balances don't shrink for the depositor.
        assert(
            // if reverted, we assert nothing about effects (revert allowed), so the implication passes
            reverted || (
                borrowATokenTotalAfter >= borrowATokenTotalBefore
                && balanceAfter >= balanceBefore
            )
        );
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

